-- CIE-10 Odontologia Ecuador - especialidad 3 (ODONTOLOGO)
-- Fuente de datos: CIE10_Odontologia_Ecuador_300.csv proporcionado para el modulo.
-- Script idempotente: actualiza registros existentes e inserta solamente los faltantes.
SET NAMES utf8mb4;
SET @usuario_odontologia = '9666666666';
SET @ip_odontologia = '127.0.0.1';
START TRANSACTION;

ON DUPLICATE KEY UPDATE estado = 1, id_especialidad = 3, id_usuariomod = @usuario_odontologia, ip_modificacion = @ip_odontologia, updated_at = NOW();

UPDATE cie_10_3 SET descripcion = 'OTRAS ENFERMEDADES INFECCIOSAS Y LAS NO ESPECIFICADAS', estado = 1, id_especialidad = 3, id_usuariomod = @usuario_odontologia, ip_modificacion = @ip_odontologia, updated_at = NOW() WHERE id = 'B99';
UPDATE cie_10_3 SET descripcion = 'TUMOR MALIGNO DE LA BASE DE LA LENGUA', estado = 1, id_especialidad = 3, id_usuariomod = @usuario_odontologia, ip_modificacion = @ip_odontologia, updated_at = NOW() WHERE id = 'C01';
UPDATE cie_10_3 SET descripcion = 'TUMOR MALIGNO DE LA GLANDULA PAROTIDA', estado = 1, id_especialidad = 3, id_usuariomod = @usuario_odontologia, ip_modificacion = @ip_odontologia, updated_at = NOW() WHERE id = 'C07';
UPDATE cie_10_3 SET descripcion = 'SECUELAS DE OTROS ACCIDENTES', estado = 1, id_especialidad = 3, id_usuariomod = @usuario_odontologia, ip_modificacion = @ip_odontologia, updated_at = NOW() WHERE id = 'Y86';
UPDATE cie_10_3 SET descripcion = 'ABSCESO PERIAMIGDALINO', estado = 1, id_especialidad = 3, id_usuariomod = @usuario_odontologia, ip_modificacion = @ip_odontologia, updated_at = NOW() WHERE id = 'J36';

ON DUPLICATE KEY UPDATE descripcion = VALUES(descripcion), id_cie_10_3 = VALUES(id_cie_10_3), estado = VALUES(estado), id_usuariomod = @usuario_odontologia, ip_modificacion = @ip_odontologia, updated_at = NOW();

COMMIT;

SELECT COUNT(*) AS padres_odontologia FROM cie_10_3 WHERE id_especialidad = 3 AND estado = 1;
SELECT COUNT(*) AS subcodigos_odontologia FROM cie_10_4 c4 INNER JOIN cie_10_3 c3 ON c3.id = c4.id_cie_10_3 WHERE c3.id_especialidad = 3 AND c3.estado = 1 AND c4.estado = 1;
